import {readFile,writeFile} from 'node:fs/promises';
import path from 'node:path';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {balancedRoundOrder} from '../../framework-comparison/src/balanced-round-order.mjs';
import {measureSsrRequest,runSsrBurst,runSustainedSsrWindow,resetSsrClientConnections} from '../../framework-comparison/src/ssr-benchmark-client.mjs';
import {startSsrWorker,stopSsrWorker,controlSsrWorker} from '../../framework-comparison/src/ssr-worker-controller.mjs';
import {settleSsrWorkerInventoryStartup} from '../../framework-comparison/src/ssr-worker-inventory.mjs';
import {availableSsrRuntimes,measureSsrArtifact,ssrEnvironmentMetadata} from '../../framework-comparison/src/ssr-run-environment.mjs';
import {aggregateSsrThroughput,summarizeSsrSamples} from '../../framework-comparison/src/ssr-benchmark-statistics.mjs';
import {startComparisonServer} from '../../framework-comparison/src/server.mjs';
const root=path.resolve('.tmp/node-output-plan'),suite=path.resolve('framework-comparison');
const variants=[{id:'baseline',entry:'baseline',adapter:'before'},{id:'array-join',entry:'baseline',adapter:'after'},{id:'combined',entry:'attributes',adapter:'after'},{id:'react'}];
const runtime=availableSsrRuntimes('node')[0],rounds=30;
const report={kind:'node-output-assembly-confirmation',createdAt:new Date().toISOString(),environment:ssrEnvironmentMetadata([runtime]),method:{populations:4,rounds,windowMs:500,concurrency:32,sequentialPerRound:10,burstRequests:16,lanes:['normal','preloaded']},artifacts:{},epochs:[],runners:{run:await readFile(path.join(root,'confirm.mjs'),'utf8'),worker:await readFile(path.join(root,'confirmation-worker.mjs'),'utf8')}};
const artifactNames=['baseline','attributes','node-adapter-before','node-adapter-after'];
async function hashArtifact(name){const data=await readFile(path.join(root,name+'.mjs'));return{bytes:data.length,sha256:createHash('sha256').update(data).digest('hex')};}
for(const name of artifactNames)report.artifacts[name]=await hashArtifact(name);
const packagePaths={server:path.resolve('packages/server/dist'),react:path.join(suite,'participants/react/dist-server')};
for(const[name,directory]of Object.entries(packagePaths))report.artifacts[name]=await measureSsrArtifact(directory);
function validate(entry,samples){for(const sample of samples){assert.ok(sample.meaningful);assert.equal(sample.hash,entry.identity.hash);assert.equal(sample.bytes,entry.identity.bytes);}}
function summarize(samples){return Object.fromEntries(variants.map(({id})=>[id,{sequential:summarizeSsrSamples(samples.sequential.filter(s=>s.id===id).map(s=>s.totalMs)),burst:summarizeSsrSamples(samples.bursts.filter(s=>s.id===id).map(s=>s.elapsedMs)),...Object.fromEntries(['normal','preloaded'].map(lane=>[lane,aggregateSsrThroughput(samples.windows.filter(s=>s.id===id&&s.lane===lane))]))}]));}
const service=await startComparisonServer();
try{
 for(let epoch=0;epoch<4;epoch++){
 const entries=balancedRoundOrder(variants,epoch).map(v=>({...v}));
 const startup=await settleSsrWorkerInventoryStartup(entries,entry=>startSsrWorker({runtime,participantId:entry.id==='react'?'react':'exact',environment:entry.id==='react'?{}:{COMPARISON_EXACT_SERVER_ENTRY:path.join(root,entry.entry+'.mjs'),COMPARISON_NODE_ADAPTER_ENTRY:path.join(root,'node-adapter-'+entry.adapter+'.mjs')},transport:'node-http',workerPath:path.join(root,'confirmation-worker.mjs'),workingDirectory:suite,serviceUrl:service.url}));
 try{
  if(startup.failure)throw startup.failure;
  let identity;
  for(const entry of entries){entry.identity=await measureSsrRequest(entry.worker.url);validate(entry,[entry.identity]);if(entry.id!=='react'){identity??=entry.identity.hash;assert.equal(entry.identity.hash,identity);}validate(entry,(await runSustainedSsrWindow(entry.worker.url,32,2000)).samples);await controlSsrWorker(entry.worker,'reset');}
  const samples={epoch,identities:Object.fromEntries(entries.map(e=>[e.id,e.identity])),sequential:[],bursts:[],windows:[]};
  for(let round=0;round<rounds;round++)for(const entry of balancedRoundOrder(entries,round,epoch))for(let request=0;request<10;request++){const sample=await measureSsrRequest(entry.worker.url);validate(entry,[sample]);samples.sequential.push({id:entry.id,round,request,totalMs:sample.totalMs,ttfbMs:sample.ttfbMs});}
  for(const entry of entries)await controlSsrWorker(entry.worker,'reset');
  for(let round=0;round<rounds;round++)for(const entry of balancedRoundOrder(entries,round,epoch)){const sample=await runSsrBurst(entry.worker.url,16,16);validate(entry,sample.samples);samples.bursts.push({id:entry.id,round,elapsedMs:sample.elapsedMs});}
  for(const lane of balancedRoundOrder(['normal','preloaded'],epoch)){
   const url=entry=>entry.worker.url+(lane==='preloaded'?'?__benchmarkPreloaded=1':'');
   for(const entry of entries){validate(entry,(await runSustainedSsrWindow(url(entry),32,2000)).samples);await controlSsrWorker(entry.worker,'reset');}
   for(let round=0;round<rounds;round++)for(const entry of balancedRoundOrder(entries,round,epoch)){
    const sample=await runSustainedSsrWindow(url(entry),32,500);validate(entry,sample.samples);samples.windows.push({id:entry.id,lane,round,requests:sample.samples.length,elapsedMs:sample.elapsedMs});
   }
   console.log('Population',epoch+1,lane,Object.fromEntries(variants.map(v=>[v.id,aggregateSsrThroughput(samples.windows.filter(s=>s.id===v.id&&s.lane===lane)).aggregateRequestsPerSecond])));
  }
  samples.summary=summarize(samples);report.epochs.push(samples);await writeFile(path.join(root,'confirmation.json'),JSON.stringify(report,null,2));
 }finally{for(const worker of startup.workers)await stopSsrWorker(worker);resetSsrClientConnections();}
 }
 report.summary=summarize(Object.fromEntries(['sequential','bursts','windows'].map(key=>[key,report.epochs.flatMap(e=>e[key])])));
 for(const name of artifactNames)assert.deepEqual(await hashArtifact(name),report.artifacts[name]);
 for(const[name,directory]of Object.entries(packagePaths))assert.deepEqual(await measureSsrArtifact(directory),report.artifacts[name]);
 report.complete=true;await writeFile(path.join(root,'confirmation.json'),JSON.stringify(report,null,2));console.log('FINAL',JSON.stringify(report.summary));
}finally{await service.close();}

