import {writeNodeResponse as writeJoinedResponse} from '@exactjs/node-adapter';
import {exactResponseBodyOf} from '@exactjs/server';
import {once} from 'node:events';

export function writeNodeResponse(response,result,signal){
 const mode=process.env.COMPARISON_OUTPUT_PLAN??'joined';
 if(mode==='joined')return writeJoinedResponse(response,result,signal);
 return writeQueuedResponse(response,result,signal,mode);
}

async function writeQueuedResponse(response,result,signal,mode){
 const body=exactResponseBodyOf(result);
 if(body?.kind!=='produced'||!body.writeSynchronously)return writeJoinedResponse(response,result,signal);
 response.statusCode=result.status;
 for(const[name,value]of Object.entries(result.headers))response.setHeader(name,value);
 const pending=[];
 let bytes=0,tail='';
 const write=chunk=>{
  if(mode==='sized-callbacks')bytes+=Buffer.byteLength(chunk);
  if(mode==='chunks')pending.push(chunk);
  else if(mode==='coalesced-callbacks')pending.push(()=>{
   tail+=chunk;
   if(tail.length<16*1024)return true;
   const ready=response.write(tail);tail='';return ready;
  });
  else pending.push(()=>response.write(chunk));
 };
 try{
  const completion=body.writeSynchronously(write,{encodedByteLength:Buffer.byteLength});
  if(completion)await completion;
  if(mode==='sized-callbacks')response.setHeader('content-length',bytes);
  signal?.throwIfAborted();
  response.cork();
  try{
   for(const item of pending){
    signal?.throwIfAborted();
    const ready=mode==='chunks'?response.write(item):item();
    if(!ready){response.uncork();await once(response,'drain',{signal});response.cork();}
   }
  }finally{response.uncork();}
  response.end(tail);
 }catch(error){
  try{await body.cancel(error);}catch{}
  if(!response.headersSent){
   for(const name of response.getHeaderNames())response.removeHeader(name);
   response.statusCode=500;response.setHeader('content-type','application/json; charset=utf-8');
   response.end(JSON.stringify({error:'internal_error'}));
  }else if(!response.destroyed)response.destroy(error);
 }
}

